  async function executeAgentActions(actions,canvas,grants){
    if(!actions?.length||current.current.canvasId!==canvas)return;
    const allowed=Object.fromEntries(Object.keys(grants).map(key=>[key,grants[key]&&current.current.agentPermissions[key]]));
    const plan=planActions(current.current.nodes,current.current.edges,actions,allowed,{defaults:newGenerationData});
    // Persist a pre-edit version before an Agent can remove or overwrite anything.
    await captureVersion(false);if(current.current.canvasId!==canvas)throw new Error('画布已切换，Agent 操作已取消');
    const latest=planActions(current.current.nodes,current.current.edges,actions,allowed,{defaults:newGenerationData});
    checkpoint();current.current={...current.current,nodes:renumberNodes(latest.nodes),edges:latest.edges};setNodes(latest.nodes);setEdges(latest.edges);
    await saveNow();
    for(const id of latest.generate){if(current.current.canvasId!==canvas||!current.current.agentPermissions.generate)break;await generate(id);}
    notify(`已执行 ${actions.length} 项 Agent 操作；生成结果以节点状态为准`);
  }
  async function send(){
    if(!prompt.trim()||agentPending.current||!current.current.ready)return;
    agentPending.current=true;const state=current.current,canvas=state.canvasId,content=prompt;
    const history=state.messages.filter(message=>['user','assistant'].includes(message.role)).map(({role,text})=>({role,text}));
    let bindings;try{bindings=resolveMentions(content,state.agentMentions,state.nodes);}catch(error){agentPending.current=false;notify(error.message);return;}const grants={...state.agentPermissions};const context=canvasAgentContext({...state,referenceIds:[...new Set([...state.agentRefs,...bindings.map(m=>m.nodeId)])]});setPrompt('');setAgentMentions([]);setMessages(list=>[...list,{role:'user',text:content}]);setSending(true);
    try{const value=await api('/chat',json({prompt:content,context,history,permissions:grants}));if(value.model)setConfig(conf=>({...conf,agentModel:value.model,agentStatus:'verified',agentError:''}));if(current.current.canvasId===canvas){setMessages(list=>[...list,{role:'assistant',text:value.text}]);await executeAgentActions(value.actions,canvas,grants);}}
    catch(error){if(current.current.canvasId===canvas)setMessages(list=>[...list,{role:'error',text:error.message}]);setConfig(conf=>({...conf,agentStatus:'error',agentError:error.message}));}
    finally{agentPending.current=false;setSending(false);}
  }
