  async function importCanvas(file){if(agentPending.current||uploading.current){notify('请等当前对话或素材上传完成后导入画布');return;}try{const value=JSON.parse(await file.text());const id=crypto.randomUUID();await api('/canvases/'+id,json(value,'PUT'));await load(id);}catch(error){notify(error.message);}}
  async function manageCanvases(action,ids,patch={}){
    if(agentPending.current||uploading.current)throw new Error('请等当前对话或素材上传完成后管理画布');
    await saveNow();
    const result=await api('/canvas-management',json({action,ids,...patch}));
    const active=result.updated.find(p=>p.id===current.current.canvasId);
    if(active){
      revisions.current.set(active.id,active.updatedAt);
      if(action==='rename'){current.current.name=active.name;setName(active.name);}
      if(action==='delete'){
        clearTimeout(saveTimer.current);current.current.ready=false;setReady(false);
        localStorage.removeItem('tapnow-draft-'+active.id);localStorage.removeItem('tapnow-canvas');
        const remaining=await api('/canvases');
        if(remaining.length)await load(remaining[0].id);
        else{const id=crypto.randomUUID();await api('/canvases/'+id,json({name:'Untitled',nodes:[],edges:[],messages:[]},'PUT'));await load(id);}
      }
    }
    return result;
  }
